-- DRAFT ONLY. Run in a disposable DB after reviewing the schema draft.
BEGIN;
SELECT plan(29);
SELECT ok(to_regclass('public.srk_ai_conversations') IS NOT NULL,'conversations table exists');
SELECT ok(to_regclass('public.srk_ai_messages') IS NOT NULL,'messages table exists');
SELECT ok(to_regclass('public.srk_ai_idempotency') IS NOT NULL,'idempotency table exists');
SELECT ok(to_regclass('public.srk_ai_handoffs') IS NOT NULL,'handoffs table exists');
SELECT ok(to_regclass('public.srk_ai_audit_events') IS NOT NULL,'audit table exists');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.srk_ai_conversations'::regclass),'conversation RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.srk_ai_messages'::regclass),'message RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.srk_ai_idempotency'::regclass),'idempotency RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.srk_ai_handoffs'::regclass),'handoff RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.srk_ai_audit_events'::regclass),'audit RLS enabled');
SELECT ok(NOT has_table_privilege('anon','public.srk_ai_conversations','SELECT'),'anon cannot read conversations');
SELECT ok(NOT has_table_privilege('authenticated','public.srk_ai_conversations','SELECT'),'authenticated cannot read conversations');
SELECT ok(NOT has_table_privilege('authenticated','public.srk_ai_messages','INSERT'),'authenticated cannot insert messages');
SELECT ok(NOT has_table_privilege('authenticated','public.srk_ai_idempotency','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'authenticated cannot access idempotency');
SELECT ok(NOT has_table_privilege('authenticated','public.srk_ai_handoffs','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'authenticated cannot access handoffs');
SELECT ok(NOT has_table_privilege('authenticated','public.srk_ai_audit_events','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'authenticated cannot access audit');
SELECT ok(has_table_privilege('service_role','public.srk_ai_conversations','SELECT,INSERT,UPDATE,DELETE'),'service role can operate conversations');
SELECT ok(has_table_privilege('service_role','public.srk_ai_audit_events','INSERT'),'service role can append audit');
SELECT ok(NOT has_table_privilege('service_role','public.srk_ai_audit_events','UPDATE,DELETE'),'service role cannot mutate audit history');
SELECT ok(EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.srk_ai_conversations'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%module_key%'),'module keys constrained');
SELECT ok(EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.srk_ai_messages'::regclass AND contype='u' AND pg_get_constraintdef(oid) ILIKE '%conversation_id%sequence_no%'),'message sequence unique');
SELECT ok(EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.srk_ai_idempotency'::regclass AND contype='u' AND pg_get_constraintdef(oid) ILIKE '%owner_user_id%endpoint_key%idempotency_key%'),'idempotency scope unique');
SELECT ok(to_regclass('public.srk_ai_handoffs_one_open_per_conversation_uidx') IS NOT NULL,'one-open-handoff index exists');
SELECT ok(EXISTS(SELECT 1 FROM pg_index WHERE indexrelid='public.srk_ai_handoffs_one_open_per_conversation_uidx'::regclass AND indisunique AND indpred IS NOT NULL),'handoff uniqueness is partial');
SELECT ok(EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.srk_ai_audit_events'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%event_type%'),'audit event types constrained');
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename IN ('srk_ai_conversations','srk_ai_messages','srk_ai_idempotency','srk_ai_handoffs','srk_ai_audit_events') AND roles && ARRAY['anon','authenticated']::name[]),'no browser policies exist');
SELECT ok(NOT has_table_privilege('anon','public.srk_ai_audit_events','INSERT'),'anon cannot append audit events');
SELECT * FROM finish();
ROLLBACK;
